const STOREFRONT_QUERY = `
  query GetProducts($first: Int!) {
    products(first: $first) {
      edges {
        node {
          id
          title
          handle
          priceRange {
            minVariantPrice {
              amount
              currencyCode
            }
          }
          images(first: 1) {
            edges {
              node {
                url
                altText
              }
            }
          }
        }
      }
    }
  }
`;

const response = await fetch(
  `https://${process.env.SHOPIFY_SHOP_DOMAIN}/api/2025-01/graphql.json`,
  {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Storefront-Access-Token': process.env.SHOPIFY_STOREFRONT_ACCESS_TOKEN!,
    },
    body: JSON.stringify({
      query: STOREFRONT_QUERY,
      variables: { first: 20 },
    }),
  }
);

const { data } = await response.json();
const products = data.products.edges.map((edge: any) => edge.node);
console.log('Products:', products);

import '@shopify/shopify-api/adapters/node';
import { shopifyApi, ApiVersion } from '@shopify/shopify-api';

const shopify = shopifyApi({
  apiKey: process.env.SHOPIFY_API_KEY!,
  apiSecretKey: process.env.SHOPIFY_API_SECRET!,
  adminApiAccessToken: process.env.SHOPIFY_ADMIN_API_TOKEN!,
  hostName: process.env.SHOPIFY_SHOP_DOMAIN!,
  apiVersion: ApiVersion.January25,
  isEmbeddedApp: false,
});

const client = new shopify.clients.Rest({
  session: {
    shop: process.env.SHOPIFY_SHOP_DOMAIN!,
    accessToken: process.env.SHOPIFY_ADMIN_API_TOKEN!,
  } as any,
});

const response = await client.post({
  path: 'orders',
  data: {
    order: {
      email: 'customer@example.com',
      financial_status: 'paid',
      line_items: [
        {
          title: 'Custom T-Shirt',
          price: '29.99',
          quantity: 2,
          requires_shipping: true,
        },
      ],
      billing_address: {
        first_name: 'Jane',
        last_name: 'Doe',
        address1: '123 Main St',
        city: 'San Francisco',
        province: 'California',
        country: 'United States',
        zip: '94101',
      },
    },
  },
});

const order = response.body as any;
console.log('Created order ID:', order.order.id);
